commands:
$nvidiaSmiPath = 'C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe'

if (Test-Path $nvidiaSmiPath) {
    Write-Host "Found nvidia-smi.exe, disabling ECC..." -ForegroundColor Green
    & $nvidiaSmiPath -e 0
    Write-Host "ECC disabled successfully!" -ForegroundColor Green
    Write-Host "Note: This only works on Quadro/Tesla GPUs. GeForce cards will show an error." -ForegroundColor Yellow
} else {
    Write-Host "ERROR: nvidia-smi.exe not found at $nvidiaSmiPath" -ForegroundColor Red
    Write-Host "This optimization requires NVIDIA driver with nvidia-smi tool." -ForegroundColor Yellow
}

